run_wizard() {

TOTAL_STAGES=13
REGION="us-east-1"
CONSOLE="https://${REGION}.console.aws.amazon.com"
BUCKET_DEFAULT="careconnect-approved-docs"
ISSUE_TAG=1   # spec issue #1, the CareConnect system. This deployment outlives the wizard PR, so it is lifecycle=permanent like infra/factory-account.yaml
TAGS="Project=careconnect, issue=$ISSUE_TAG, lifecycle=permanent"

# ── Local helpers (stage-only; the library above stays untouched) ─────────
# have_aws is true when the AWS CLI is installed and signed in.
have_aws() { command -v aws >/dev/null 2>&1 && aws sts get-caller-identity >/dev/null 2>&1; }

# verify "label" cmd... runs a read-only AWS CLI check. On failure it lets the
# human fix the console step and retry. Without a signed-in CLI it asks the
# human to confirm by eye.
verify() {
  local label="$1"; shift
  if ! have_aws; then
    warn "AWS CLI not signed in, so I cannot check: $label"
    confirm "Did you confirm this by eye in the console?" || SKIPPED+=("unverified: $label")
    return 0
  fi
  until "$@" >/dev/null 2>&1; do
    warn "check failed: $label"
    confirm "Fixed it in the console? Retry the check?" || { SKIPPED+=("failed check: $label"); return 0; }
  done
  printf '  %s✓ checked%s %s\n' "$GREEN" "$RESET" "$label"
}

# need_match VAR REGEX "hint" re-asks until $VAR matches REGEX.
need_match() {
  local key="$1" re="$2" hint="$3"
  until [[ "${!key}" =~ $re ]]; do
    warn "That does not look right. $hint"
    ask "$key" "Paste it again:"
  done
}

banner "CareConnect: AWS deployment (capped account, then build steps 5 to 17)"

# ── 1. Capped account stack (ADR 0001) ────────────────────────────────────
stage "Capped account: \$20 budget and OIDC role"
say "Use a NEW AWS account used only for CareConnect. The stack adds a \$20 budget"
say "(email alerts at 50% and 90%) and a GitHub OIDC role. At 100% the stack blocks only the factory role."
warn "Resources you create in this wizard are NOT stopped at 100%. They keep billing until you delete them."
note "Treat the 50% and 90% emails as the signal to tear down."
note "Sign in to the new account first. Region must be N. Virginia (us-east-1)."
open_url "$CONSOLE/cloudformation/home?region=$REGION#/stacks/create"
step "Choose 'Upload a template file' and pick infra/factory-account.yaml from this repo."
step "Stack name: careconnect-factory-account"
step "AlertEmail: your email. GitHubRepo: leave the default."
step "ExistingOidcProviderArn: leave blank, unless this account already has a GitHub OIDC provider."
step "Tick the IAM acknowledgement box, then Submit. Wait for CREATE_COMPLETE (about 2 minutes)."
step "Open your email and click 'Confirm subscription' in the AWS Notifications message."
pause "Stack is CREATE_COMPLETE and email confirmed?"
step "Stack > Outputs tab > copy FactoryRoleArn."
ask FACTORY_ROLE_ARN "Paste FactoryRoleArn:"
need_match FACTORY_ROLE_ARN '^arn:aws:iam::[0-9]{12}:role/.+' "It starts with arn:aws:iam::<12 digits>:role/"
write_env FACTORY_ROLE_ARN "$FACTORY_ROLE_ARN"
AWS_ACCOUNT_ID=$(sed -E 's/^arn:aws:iam::([0-9]{12}):.*/\1/' <<<"$FACTORY_ROLE_ARN")
write_env AWS_ACCOUNT_ID "$AWS_ACCOUNT_ID"
if have_aws; then
  signed=$(aws sts get-caller-identity --query Account --output text 2>/dev/null || true)
  if [[ "$signed" != "$AWS_ACCOUNT_ID" ]]; then
    warn "AWS CLI is signed in to $signed, but the stack lives in $AWS_ACCOUNT_ID."
    warn "Later checks will fail until you sign the CLI in to $AWS_ACCOUNT_ID."
  fi
fi
verify "the \$20 budget exists" bash -c "[[ -n \$(aws budgets describe-budgets --account-id $AWS_ACCOUNT_ID --query 'Budgets[?to_number(BudgetLimit.Amount)==\`20\`].BudgetName | [0]' --output text | grep -v None) ]]"
note "Tag every resource you create below with: $TAGS"

# ── 2. S3 approved documents (step 5) ─────────────────────────────────────
stage "Step 5: S3 bucket with approved documents"
say "Only files in approved/ may feed answers. The wizard uploads them for you."
open_url "$CONSOLE/s3/bucket/create?region=$REGION"
step "Bucket name (must be globally unique). Suggested: ${BUCKET_DEFAULT}-${AWS_ACCOUNT_ID}"
step "Leave 'Block all public access' ON. Add tags $TAGS. Create bucket."
ask S3_BUCKET "Bucket name you created:"
write_env S3_BUCKET "$S3_BUCKET"
if have_aws && confirm "Upload Docs/Repo/careconnect-approved-docs/approved/ to s3://$S3_BUCKET/approved/ now?"; then
  aws s3 sync Docs/Repo/careconnect-approved-docs/approved "s3://$S3_BUCKET/approved/" --region "$REGION" || {
    warn "Upload failed. Upload by hand instead."
    step "Console > your bucket > Upload > drag the files from Docs/Repo/careconnect-approved-docs/approved/ into a folder named approved/"
    pause "Upload done?"
  }
else
  step "Console > your bucket > Upload > drag the files from Docs/Repo/careconnect-approved-docs/approved/ into a folder named approved/"
  pause "Upload done?"
fi
verify "approved/ has files" aws s3api head-object --bucket "$S3_BUCKET" --key approved/billing-faq.md

# ── 3. Knowledge Base (step 6) ────────────────────────────────────────────
stage "Step 6: Bedrock Knowledge Base on S3 Vectors"
warn "Pick S3 Vectors as the vector store. Never pick OpenSearch Serverless (provisioned cost)."
open_url "$CONSOLE/bedrock/home?region=$REGION#/knowledge-bases/create"
step "Name: careconnect-kb. Data source: Amazon S3, URI s3://$S3_BUCKET/approved/"
step "Embeddings model: Titan Text Embeddings V2. Vector store: Amazon S3 Vectors (quick create)."
step "Tags: $TAGS."
step "Create. Then open the data source and click Sync. Wait for status 'Available'."
step "Copy the Knowledge Base ID from the top of the page (10 characters)."
ask CARECONNECT_KB_ID "Paste Knowledge Base ID:"
need_match CARECONNECT_KB_ID '^[A-Z0-9]{10}$' "It is 10 capital letters and digits."
write_env CARECONNECT_KB_ID "$CARECONNECT_KB_ID"
verify "Knowledge Base is ACTIVE" bash -c "[[ \$(aws bedrock-agent get-knowledge-base --knowledge-base-id $CARECONNECT_KB_ID --region $REGION --query knowledgeBase.status --output text) == ACTIVE ]]"

# ── 4. Guardrail (step 7) ─────────────────────────────────────────────────
