verify "Guardrail version exists" aws bedrock get-guardrail --guardrail-identifier "$CARECONNECT_GUARDRAIL_ID" --guardrail-version "$CARECONNECT_GUARDRAIL_VERSION" --region "$REGION"

# ── 5. Deterministic safety Lambda (step 8) ───────────────────────────────
