write_env CARECONNECT_STATE_MACHINE_ARN "$CARECONNECT_STATE_MACHINE_ARN"
verify "state machine exists" aws stepfunctions describe-state-machine --state-machine-arn "$CARECONNECT_STATE_MACHINE_ARN" --region "$REGION"

# ── 8. Local smoke test (steps 9, 10, 12, 14) ─────────────────────────────
stage "Steps 9 to 14: run the Supervisor on your dev box"
write_env AWS_REGION "$REGION"
say "The agents read these five values from the environment:"
note "CARECONNECT_KB_ID, CARECONNECT_GATEWAY_URL, CARECONNECT_GUARDRAIL_ID,"
