write_env API_URL "$API_URL"

# ── 12. Frontend (step 17) ────────────────────────────────────────────────
stage "Step 17: Frontend in S3 and CloudFront"
BUILD_DIR=$(mktemp -d)/frontend
mkdir -p "$BUILD_DIR"
cp -R src/frontend/. "$BUILD_DIR/"
sed -E "s#API_URL: \"[^\"]*\"#API_URL: \"${API_URL}\"#" src/frontend/config.js > "$BUILD_DIR/config.js"
