step "Cost: choose the cheapest price class. Create, and let the bucket policy update."
step "Wait for Status: Deployed. Copy the Distribution domain name."
ask CLOUDFRONT_DOMAIN "Paste domain (for example d1234abcd.cloudfront.net):"
need_match CLOUDFRONT_DOMAIN '^d[a-z0-9]+\.cloudfront\.net$' "Expected dxxxx.cloudfront.net, with no https://"
write_env CLOUDFRONT_DOMAIN "$CLOUDFRONT_DOMAIN"

# ── 13. Close the loop: ALLOWED_ORIGIN, then test ─────────────────────────
stage "Set ALLOWED_ORIGIN and test the site"
ALLOWED_ORIGIN="https://${CLOUDFRONT_DOMAIN}"
write_env ALLOWED_ORIGIN "$ALLOWED_ORIGIN"
open_url "$CONSOLE/lambda/home?region=$REGION#/functions/careconnect-agentcore-proxy"
step "Code tab > lambda_function.py: set ALLOWED_ORIGIN to exactly:"
printf '      %s%s%s\n' "$BOLD" "$ALLOWED_ORIGIN" "$RESET"
note "No trailing slash. Never use \"*\". Click Deploy."
pause "Deployed?"
if have_aws; then
  aws cloudfront create-invalidation --distribution-id "$(aws cloudfront list-distributions --query "DistributionList.Items[?DomainName=='${CLOUDFRONT_DOMAIN}'].Id | [0]" --output text)" --paths '/*' >/dev/null 2>&1 \
    && say "CloudFront cache invalidated." || step "CloudFront > your distribution > Invalidations > Create > path /*"
else
  step "CloudFront > your distribution > Invalidations > Create > path /*"
fi
open_url "$ALLOWED_ORIGIN"
step "Ask a routine question: expect a cited answer. Ask a dosage question: expect an escalation notice."
step "Browser DevTools > Console must show no CORS error."
pause "Both worked?"
note "Costs: check Billing > Budgets in a week. When done testing, delete the resources tagged issue=$ISSUE_TAG that you no longer need."

finish
}

run_wizard "$@"; exit
